function renderVisual(target,a,front=false,auto=false){const label=node('small',front?'Figura do enunciado':mediaState(a),'muted');target.append(label);if(!front){target.append(node('strong',a.title||'Imagem'));if(a.visual?.description)textBlock(target,a.visual.description);if(a.visual?.pendingReason&&!a.fileId)textBlock(target,'PENDENTE: '+a.visual.pendingReason);if(a.legacyMedia&&!a.fileId){textBlock(target,a.legacyMedia.status);if(a.legacyMedia.lastTransferError)textBlock(target,a.legacyMedia.lastTransferError.message)}}if(!a.fileId){if(!front&&a.url)target.append(link(a.url,'Consultar referência externa'));return}let requested=false;async function load(){if(requested||!authenticated)return;requested=true;const subject=drive.identity.id;try{const r=await drive.attachmentBytes(a.fileId,'media');if(!authenticated||drive.identity?.id!==subject||!target.isConnected)return;const url=URL.createObjectURL(new Blob([r.bytes],{type:r.type}));objectUrls.add(url);if(!front&&a.visual)label.textContent=mediaState(a,false,true);const img=node('img');img.alt=front?'Figura original do enunciado':(a.visual?.description||a.title||'Imagem vinculada');img.className='bm-private-visual';img.onload=()=>{if(target.isConnected&&authenticated&&drive.identity?.id===subject)label.textContent=front?'Figura do enunciado — carregada':(a.visual?mediaState(a,true):'Original legado carregado nesta sessão')};img.onerror=()=>{label.textContent='PENDENTE — falha de exibição';requested=false;URL.revokeObjectURL(url);objectUrls.delete(url);img.remove()};target.append(img);img.src=url}catch(e){if(target.isConnected)label.textContent='PENDENTE — '+e.message;requested=false}}if(!front)attachmentControls(target,a,'media');target.append(button('Carregar figura',()=>void load()));if(auto)void load()}
