function numberField(f,label,name,value,min,max,step='1'){const el=field(f,label,name,String(value));el.type='number';el.min=String(min);el.max=String(max);el.step=step;el.required=true;return el}
function subjectOptions(f,name,selected='',all=false){const s=selectChoices(f,'Disciplina',[['',all?'Todas':'Selecione'],...planData().subjects.map(x=>[x.id,x.name])],selected,()=>{});s.name=name;s.required=!all;return s}
