function studyTimer(){const p=panel('Cronômetro de horas líquidas');textBlock(p,'O cronômetro é local à sessão autenticada. Pausar exclui o tempo de descanso. Ainda não há transferência de cronômetro ativo entre dispositivos.');const f=node('div');p.append(f);const s=subjectOptions(f,'subjectId',studyClock.subjectId),t=typeOptions(f,'type',studyClock.type),topic=field(f,'Assunto','timerTopic',studyClock.topic);const locked=!!(studyClock.runningAt||studyClock.elapsed);s.disabled=t.disabled=topic.disabled=locked;const display=node('strong','','bm-clock-display');display.id='studyClockDisplay';p.append(display);const row=node('div','','row');row.append(button(studyClock.runningAt?'Pausar':'Iniciar / continuar',()=>{if(studyClock.runningAt)pauseStudyClock();else{if(!studyClock.elapsed){if(!s.value)throw Error('Selecione uma disciplina');studyClock.subjectId=s.value;studyClock.type=t.value;studyClock.topic=topic.value;studyClock.firstAt=Date.now()}studyClock.runningAt=Date.now()}render()},'primary'),button('Encerrar e salvar',()=>{if(!studyClock.runningAt&&!studyClock.elapsed)throw Error('Nenhum tempo registrado');if(!studyClock.subjectId)throw Error('Selecione uma disciplina');const seconds=timerSeconds(studyClock,Date.now());if(seconds<1)throw Error('Duração mínima: um segundo');const row={id:id(),at:new Date(studyClock.firstAt).toISOString(),date:localDate(new Date(studyClock.firstAt)),seconds,subjectId:studyClock.subjectId,type:studyClock.type,topic:studyClock.topic,questions:0,correct:0,notes:''};write(d=>d.sessions.push(row));resetStudyClock();render()}),button('Descartar',()=>{if(confirm('Descartar tempo não registrado?')){resetStudyClock();render()}}));p.append(row);updateStudyClock()}
function pauseStudyClock(){if(studyClock.runningAt){studyClock.elapsed+=Math.max(0,Date.now()-studyClock.runningAt);studyClock.runningAt=0}updateStudyClock()}
function resetStudyClock(){studyClock={elapsed:0,runningAt:0,firstAt:0,subjectId:'',type:'Teoria',topic:''};updateStudyClock()}
