function methodology(){title('Metodologia Mestre v014');const p=panel('A mesma metodologia do projeto Concurso');textBlock(p,'Norma pedagógica integral, incluindo os 33 critérios PMS-1 e todos os adendos vigentes em 23/11/2026. Somente os destinos e identificadores operacionais mudam. A metodologia integral é a referência de estudo; a cópia da Nina foi preservada no Drive separado. A implantação não importa arquivos legados automaticamente.');for(const [t,x] of [['Estudo','Resolver, explicar, registrar lacunas reais, buscar cobertura por ID, conceito, sinônimo, fonte, frente, verso, módulos e histórico. Evoluir o mesmo ID quando houver cobertura. Propostas exigem as aprovações vigentes.'],['Cartões','Resposta-modelo integrada e 11 critérios internos. Preservar originais, versões, fontes e relações recíprocas. Figuras explicativas no verso, SVG colorido legível e associado à questão/cartão.'],['SRS','Questão normal: 16 dias para o cartão direto e relacionados; Difícil: 8 dias. Formal: Difícil 8, Bom 16, Fácil 24, Conhecimento preservado 32, Conhecimento adquirido 64 (duas avaliações formais Fácil anteriores, até esclarecer progressão). Errei eliminado das novas avaliações; erro real continua registrado como lacuna. Difícil é o menor prazo (8 dias). Referências 5 = Bom 16d, 10 = Fácil 24d, salvo questão difícil. Sem avaliação inventada.'],['Portão de cobertura','Não declarar ausência sem verificar fonte vigente, aprovados e incrementos. Distinguir cobertura direta, parcial, complementar e busca parcial. Corrigir omissões verificadas.'],['Separação','Não consultar nem gravar dados privados, SRS, IDs operacionais ou arquivos do Concurso para estudar na Banco Mestre.']]){const d=panel(t);textBlock(d,x)}const z=panel('Limites de implementação');textBlock(z,'O portal aplica os intervalos, referências válidas registradas, pesquisa ampliada, aprovação e histórico locais. Grifos avançados, editor SVG, busca legada no Drive e automações do projeto original ainda exigem implementação. Sincronização do novo banco e arquivos privados usa a identidade Google. A metodologia integral continua obrigatória no estudo pelo chat.');}
function migrationPanel(){const p=panel('Migração inicial do Banco Mestre privado');textBlock(p,'Somente para o proprietário da fonte legada. O Google solicitará autorização de leitura do Drive em separado. Informe o ID do seu snapshot privado (família BancoMestrePrivadoV159), e opcionalmente o SHA-256 do ponteiro. Nenhum dado é lido automaticamente nem enviado ao GitHub.');if(!emptyTarget(db)){textBlock(p,'Migração inicial indisponível: já existem registros. Nenhum dado será mesclado ou substituído.');if(db.legacyImport)textBlock(p,JSON.stringify(db.legacyImport,null,2));return}const f=node('form');p.append(f);field(f,'ID do snapshot privado','sourceId').required=true;field(f,'SHA-256 esperado (opcional; recomendado)','sha');const b=node('button','Verificar fonte e preparar prévia','primary');b.type='submit';f.append(b);const report=node('div');p.append(report);f.onsubmit=async e=>{e.preventDefault();if(!authenticated||fileBusy||saving||dirty||!emptyTarget(db))return;fileBusy=true;updateAuth();b.disabled=true;report.replaceChildren();const subject=drive.identity.id,rev=revision;try{const v=Object.fromEntries(new FormData(f));const src=await drive.readLegacySource(v.sourceId.trim(),v.sha.trim().toLowerCase());if(!authenticated||drive.identity.id!==subject||revision!==rev||!emptyTarget(db)||!report.isConnected)throw Error('Sessão ou destino alterados.');const planned=validate(planLegacy(src.raw,src.receipt,db)),summary=migrationSummary(planned);textBlock(report,'Fonte '+planned.legacyImport.version+' · SHA-256 '+src.receipt.sha256+' · conta proprietária confirmada.');for(const [k,label] of Object.entries({cards:'Cartões',active:'Ativos',archived:'Inativos preservados',questions:'Questões',images:'Registros de mídia pendentes de cópia',srs:'SRS históricos preservados',scheduled:'Ativos com vencimento conhecido',withoutDate:'Ativos sem vencimento — fora da fila automática',swapped:'Campos antigos invertidos identificados',missingLinks:'Vínculos não resolvidos'}))textBlock(report,label+': '+summary[k]);const accept=node('button','Confirmar migração deste catálogo para minha conta','primary');accept.type='button';report.append(accept);accept.onclick=()=>{if(fileBusy||saving||dirty||!authenticated||drive.identity.id!==subject||revision!==rev||!emptyTarget(db)||!report.isConnected)return;if(!confirm('Importar exclusivamente para '+drive.identity.email+'? O snapshot original permanece intacto; arquivos e grifos externos ainda estarão pendentes.'))return;fileBusy=true;accept.disabled=true;updateAuth();try{write(d=>Object.assign(d,planned));status('Catálogo importado em memória. Confirmação depende da sincronização privada.');render()}catch(err){status(err.message)}finally{fileBusy=false;updateAuth()}}}catch(err){status(err.message)}finally{fileBusy=false;b.disabled=false;updateAuth()}}}
function transferPanel(){const p=panel('Transferência privada de originais históricos');textBlock(p,'Selecione arquivos do seu próprio Drive. Autorização separada de leitura, mesma identidade Google, conferência SHA-256 na origem e no destino. Limite atual: 20 MB por arquivo. Os originais nunca são alterados. Não transfere arquivos compartilhados ou de outra conta.');
if(db.legacyImport?.owner===drive.identity.id){const pending=pendingImages(db);textBlock(p,pending.length+' imagens históricas aguardando cópia. Selecione até cinco por operação. Vínculos a propostas ausentes permanecem pendentes.');const chosen=[];for(const a of pending){const l=node('label');const cb=node('input');cb.type='checkbox';cb.style.width='auto';cb.disabled=!a.legacyMedia.originalFileId||!a.legacyMedia.sha256;l.append(cb,document.createTextNode(' '+a.id+' · '+a.title));p.append(l);chosen.push({a,cb})}const result=node('div');const start=node('button','Transferir imagens selecionadas','primary');start.type='button';p.append(start,result);start.onclick=async()=>{const selection=chosen.filter(x=>x.cb.checked).map(x=>x.a);if(!selection.length||selection.length>5){status('Selecione de 1 a 5 imagens.');return}if(fileBusy||saving||dirty||!authenticated)return;const owner=drive.identity.id,rev=revision;fileBusy=true;start.disabled=true;updateAuth();const ok=[],errors=[];try{await drive.withLegacyReader(async copy=>{for(const a of selection){if(!authenticated||drive.identity.id!==owner||revision!==rev)throw Error('Sessão alterada; cópias verificadas podem ser reutilizadas.');try{ok.push({id:a.id,receipt:await copy(a.legacyMedia.originalFileId,'media',a.legacyMedia.sha256)})}catch(e){errors.push({id:a.id,error:String(e.message).slice(0,300)})}}});if(!authenticated||drive.identity.id!==owner||revision!==rev)throw Error('Sessão alterada');write(d=>{for(const x of ok)applyMediaTransfer(d,x.id,x.receipt,owner);for(const x of errors){const a=d.media.find(y=>y.id===x.id&&!y.fileId);if(a)a.legacyMedia.lastTransferError={at:new Date().toISOString(),message:x.error}}});status(ok.length+' cópias verificadas; '+errors.length+' pendências. Catálogo em sincronização.');render()}catch(e){status(e.message)}finally{fileBusy=false;start.disabled=false;updateAuth()}}}
const f=node('form');p.append(f);field(f,'ID do PDF no seu Drive','sourceId').required=true;field(f,'SHA-256 esperado, se conhecido','expectedSha');field(f,'Título','title').required=true;field(f,'Assunto','topic');field(f,'Fonte/edição','source');field(f,'IDs dos cartões pertinentes','related');const s=node('button','Copiar PDF privado','primary');s.type='submit';f.append(s);f.onsubmit=async e=>{e.preventDefault();if(fileBusy||saving||dirty||!authenticated)return;const v=Object.fromEntries(new FormData(f)),owner=drive.identity.id,rev=revision,sourceId=v.sourceId.trim();if(db.pdf.some(p=>p.legacyTransfer?.sourceId===sourceId)){status('PDF já registrado nesta conta.');return}const cardIds=uniqueIds(v.related);if(cardIds.some(id=>!db.cards.some(c=>c.id===id))){status('Cartão inexistente.');return}fileBusy=true;s.disabled=true;updateAuth();try{const receipt=await drive.withLegacyReader(copy=>copy(sourceId,'pdf',v.expectedSha.trim().toLowerCase()));if(!authenticated||drive.identity.id!==owner||revision!==rev)throw Error('Sessão alterada');write(d=>createPdfTransfer(d,{...v,id:id(),sourceId,expectedSha:v.expectedSha.trim().toLowerCase(),cardIds},receipt,owner));status('PDF copiado e conferido. Grifos históricos permanecem pendentes.');render()}catch(e){status(e.message)}finally{fileBusy=false;s.disabled=false;updateAuth()}};
for(const doc of db.pdf.filter(p=>p.legacyTransfer?.owner===drive.identity.id)){const d=node('details');d.append(node('summary','Grifos históricos — '+doc.title));textBlock(d,doc.legacyTransfer.annotationStatus);textBlock(d,'Importação de JSON compatível BM-ANNOTATION-TRANSFER/1, com ID e SHA-256 do mesmo original. Não é conversão automática de IndexedDB legado. Não sobrescreve marcações existentes.');const input=node('input');input.type='file';input.accept='.json,application/json';d.append(input);const b=node('button','Importar marcações verificadas');b.type='button';d.append(b);b.onclick=async()=>{if(fileBusy||saving||dirty||!authenticated||!input.files[0])return;const owner=drive.identity.id,rev=revision;fileBusy=true;b.disabled=true;updateAuth();try{if(input.files[0].size>10*1024*1024)throw Error('JSON de grifos excede 10 MB');const payload=JSON.parse(await input.files[0].text());if(!authenticated||drive.identity.id!==owner||revision!==rev)throw Error('Sessão alterada');const bytes=await drive.attachmentBytes(doc.fileId,'pdf');if(await digestBlob(bytes.bytes)!==doc.legacyTransfer.sha256)throw Error('Original privado divergente');if(revision!==rev)throw Error('Banco alterado');write(data=>{const target=data.pdf.find(p=>p.id===doc.id);target.annotation=remapHistoricalAnnotation(target,payload,owner);target.legacyTransfer.annotationStatus='Marcações compatíveis importadas; visualização ainda não testada'});status('Marcações importadas, sem alterar SRS.');render()}catch(e){status(e.message)}finally{fileBusy=false;b.disabled=false;updateAuth()}};p.append(d)}}
function sync(){title('Backup e Google Drive');const p=panel('Armazenamento independente');textBlock(p,'Dados da conta Google autenticada. O GitHub publica apenas código; o banco fica em uma pasta particular do seu Drive.');p.append(button('Baixar backup JSON',()=>{const a=node('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({project:PROJECT,owner:drive.identity.id,data:db},null,2)],{type:'application/json'}));a.download='BancoMestre_'+localDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)},'primary'));const f=node('input');f.type='file';f.accept='.json,application/json';f.onchange=async()=>{if(!authenticated||fileBusy||saving)return;const owner=drive.identity.id,rev=revision;fileBusy=true;updateAuth();try{const payload=JSON.parse(await f.files[0].text());if(!authenticated||drive.identity.id!==owner||revision!==rev)throw Error('Sessão alterada.');if(payload.owner!==drive.identity.id||payload.project!==PROJECT)throw Error('Backup de outra conta ou de projeto incompatível. Migração legada não habilitada.');const incoming=validate(payload.data);if(!confirm('Substituir a base local pela cópia? Baixe o backup atual antes.'))return;write(d=>Object.assign(d,incoming));status('Backup recuperado em memória; sincronizando com seu Drive.');render()}catch(e){status('Importação recusada: '+e.message)}finally{fileBusy=false;updateAuth()}};p.append(node('p','Restaurar backup do próprio projeto:'),f);migrationPanel();transferPanel();const g=panel('Google Drive · conta atual');textBlock(g,drive.identity.email);g.append(link('https://drive.google.com/drive/folders/'+drive.root.id,'Abrir minha pasta privada'),button('Tentar sincronizar pendências',()=>void saveChanges(),'primary'));textBlock(g,'Cada salvamento cria um snapshot independente. Conflitos são bloqueados, não sobrescritos. PDFs e imagens são gravados em pastas separadas na conta atual. A migração inicial do catálogo exige confirmação da conta proprietária. Transferência de mídias e PDFs exige seleção e autorização; grifos legados requerem formato compatível.')}
